function CareRoutine({ morning, evening }: { morning: string[]; evening: string[] }) {
  return <div className="care-routine-grid">
    <div><span>Утро</span><ol>{morning.map((step)=><li key={step}>{step}</li>)}</ol></div>
    <div><span>Вечер</span><ol>{evening.map((step)=><li key={step}>{step}</li>)}</ol></div>
  </div>;
}

function CareTopicFAQ({ type }: { type: 'dry' | 'oily' }) {
  const items = type === 'dry' ? [
    ['Нужно ли умываться с очищающим средством утром?', 'Не всегда. Если кожа после вечернего ухода остаётся комфортной, утром некоторым людям достаточно воды. Если используется плотный ночной уход или есть ощущение загрязнения, подойдёт мягкое средство без выраженного обезжиривания.'],
    ['Чем сухая кожа отличается от обезвоженной?', 'Сухая кожа — это тип, для которого характерна более низкая выработка кожного сала. Обезвоженность — временное состояние с недостатком воды; она может встречаться и при жирной коже.'],
    ['Можно ли использовать кислоты при сухой коже?', 'Можно, если они действительно нужны под конкретную задачу и кожа хорошо их переносит. Начинайте с редкого применения и не добавляйте несколько раздражающих активов одновременно.'],
    ['Как понять, что крем слишком лёгкий?', 'Если вскоре после нанесения снова появляется стянутость, заметное шелушение или желание постоянно наносить средство повторно, текстура или состав могут быть недостаточно комфортными.'],
  ] : [
    ['Нужно ли подсушивать жирную кожу?', 'Нет. Цель ухода — не убрать весь себум, а очищать кожу без выраженной стянутости и поддерживать комфортный барьер. Слишком агрессивное обезжиривание часто усиливает раздражение.'],
    ['Нужен ли крем, если кожа и так блестит?', 'Да, но текстура может быть лёгкой: флюид, гель-крем или эмульсия. Увлажнение и жирность — не одно и то же, а обезвоженная жирная кожа нередко становится более чувствительной.'],
    ['Можно ли использовать салициловую кислоту каждый день?', 'Это зависит от формулы и переносимости. Начинать безопаснее с более редкого применения и увеличивать частоту только при отсутствии сухости, жжения и стойкого покраснения.'],
    ['Что делать с блеском в течение дня?', 'Матирующие салфетки или лёгкая пудра могут временно убрать блеск. Это косметический приём: он не заменяет базовый уход и не влияет напрямую на работу сальных желёз.'],
  ];

  return <div className="faq">{items.map(([question, answer])=><details key={question}><summary>{question}<span>+</span></summary><p>{answer}</p></details>)}</div>;
}

